def est_premier(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

# Exemple d'utilisation
print(est_premier(25))  # Retourne False
print(est_premier(23))  # Retourne True
